def check_unencrypted_rds_instances(node):
    import ast
    if isinstance(node, ast.Expression)
        if isinstance(node.value, ast.Call)
            func = node.value.func.id
            args = [arg.s for arg in node.value.args]
            if func == 'describe_db_instances'
                for db in ast.literal_eval(node.value.kwargs['kwargs']['DBInstances']):
                    if 'Encrypted' not in db or db['Encrypted'] is False:
                        return True
    return False
